    fun getStats(reply: Reply<ConnectionStats, RtcConnectionCode>)

    /**
     * Resolves with the channel's id; `dataChannelOpen` says when it can send.
     * Rejects with FAILED / CLOSED.
     */
    fun createDataChannel(label: String, options: DataChannelInit?, reply: Reply<Int, RtcConnectionCode>)

    /** Rejects with NOT_FOUND / FAILED / CLOSED. */
    fun sendText(channelId: Int, text: String, reply: Reply<Unit, RtcConnectionCode>)

    /** Rejects with NOT_FOUND / FAILED / CLOSED. */
    fun sendBinary(channelId: Int, data: ByteArray, reply: Reply<Unit, RtcConnectionCode>)

    /**
     * Bytes queued and not yet sent.
     * Rejects with NOT_FOUND.
     */
    fun getBufferedAmount(channelId: Int, reply: Reply<Double, RtcConnectionCode>)

    /** Rejects with NOT_FOUND. */
    fun setBufferedAmountLowThreshold(channelId: Int, threshold: Double, reply: Reply<Unit, RtcConnectionCode>)

    /** A no-op for an unknown id. */
    fun closeDataChannel(channelId: Int, reply: Reply<Unit, RtcConnectionCode>)

    /** The session closed (the app's close, the world's teardown): stop what it started. */
    fun close() {}
}

object RtcConnectionChannel {
    /** What the halves register under. */
    const val NAME = "rtcConnection"

    /** The contract's version: the highest `@since` of its members. */
    const val VERSION = 1

    /** Register the service: `make` builds one session from its params. It must be cheap — no
     *  prompt, no I/O: that belongs to the first call that needs it. */
    fun register(engine: LecodesEngine, make: (params: RtcConnectionParams, events: RtcConnectionEvents) -> RtcConnectionPlugin) {
        engine.registerService(NAME, VERSION) { params, channel ->
            val plugin = make(RtcConnectionParams.read(Wire.reader(params)) ?: RtcConnectionParams(), RtcConnectionEvents { event, packed -> channel.emitPacked(event, packed) })
            Services.Instance(onCall = { call -> RtcConnectionGlue.call(plugin, call.method, call.reader(), call) }, onClose = { plugin.close() })
        }
    }
}

/** Reads a call off the wire and hands it to the plugin; a malformed call never reaches it. */
internal object RtcConnectionGlue {
    fun call(plugin: RtcConnectionPlugin, method: String, r: PackedReader, settle: ChannelSettle) {
        val n = r.beginArray()   // the arguments, in their order
        when (method) {
            "createOffer" -> {
                val a0 = if (0 < n && !r.isNull()) (r.bool() ?: return settle.reject("bad arguments — RtcConnection.createOffer: iceRestart")) else { if (0 < n) r.skip(); null }
                plugin.createOffer(a0, Reply<String, RtcConnectionCode>(settle) { v, w -> w.string(v) })
            }
            "acceptOffer" -> {
                val a0 = (if (0 < n) r.string() else null) ?: return settle.reject("bad arguments — RtcConnection.acceptOffer: offer")
                plugin.acceptOffer(a0, Reply<String, RtcConnectionCode>(settle) { v, w -> w.string(v) })
            }
            "acceptAnswer" -> {
                val a0 = (if (0 < n) r.string() else null) ?: return settle.reject("bad arguments — RtcConnection.acceptAnswer: answer")
                plugin.acceptAnswer(a0, Reply<Unit, RtcConnectionCode>(settle, null))
            }
            "addIceCandidate" -> {
                val a0 = (if (0 < n) r.string() else null) ?: return settle.reject("bad arguments — RtcConnection.addIceCandidate: candidate")
                plugin.addIceCandidate(a0, Reply<Unit, RtcConnectionCode>(settle, null))
            }
            "setTrack" -> {
                val a0 = (if (0 < n) MediaKind.read(r) else null) ?: return settle.reject("bad arguments — RtcConnection.setTrack: kind")
                val a1 = if (1 < n && !r.isNull()) (r.string() ?: return settle.reject("bad arguments — RtcConnection.setTrack: trackId")) else { if (1 < n) r.skip(); null }
                plugin.setTrack(a0, a1, Reply<Unit, RtcConnectionCode>(settle, null))
            }
            "getRemoteTracks" -> {
                plugin.getRemoteTracks(Reply<RtcConnectionGetRemoteTracksResult, RtcConnectionCode>(settle) { v, w -> v.write(w) })
            }
            "setRemoteAudioMuted" -> {
                val a0 = (if (0 < n) r.bool() else null) ?: return settle.reject("bad arguments — RtcConnection.setRemoteAudioMuted: muted")
                plugin.setRemoteAudioMuted(a0, Reply<Unit, RtcConnectionCode>(settle, null))
            }
            "getStats" -> {
                plugin.getStats(Reply<ConnectionStats, RtcConnectionCode>(settle) { v, w -> v.write(w) })
            }
            "createDataChannel" -> {
                val a0 = (if (0 < n) r.string() else null) ?: return settle.reject("bad arguments — RtcConnection.createDataChannel: label")
                val a1 = if (1 < n && !r.isNull()) (DataChannelInit.read(r) ?: return settle.reject("bad arguments — RtcConnection.createDataChannel: options")) else { if (1 < n) r.skip(); null }
                plugin.createDataChannel(a0, a1, Reply<Int, RtcConnectionCode>(settle) { v, w -> w.i32(v) })
            }
            "sendText" -> {
                val a0 = (if (0 < n) r.i32() else null) ?: return settle.reject("bad arguments — RtcConnection.sendText: channelId")
                val a1 = (if (1 < n) r.string() else null) ?: return settle.reject("bad arguments — RtcConnection.sendText: text")
                plugin.sendText(a0, a1, Reply<Unit, RtcConnectionCode>(settle, null))
            }
            "sendBinary" -> {
                val a0 = (if (0 < n) r.i32() else null) ?: return settle.reject("bad arguments — RtcConnection.sendBinary: channelId")
                val a1 = (if (1 < n) r.bytes() else null) ?: return settle.reject("bad arguments — RtcConnection.sendBinary: data")
                plugin.sendBinary(a0, a1, Reply<Unit, RtcConnectionCode>(settle, null))
            }
            "getBufferedAmount" -> {
                val a0 = (if (0 < n) r.i32() else null) ?: return settle.reject("bad arguments — RtcConnection.getBufferedAmount: channelId")
                plugin.getBufferedAmount(a0, Reply<Double, RtcConnectionCode>(settle) { v, w -> w.f64(v) })
            }
            "setBufferedAmountLowThreshold" -> {
                val a0 = (if (0 < n) r.i32() else null) ?: return settle.reject("bad arguments — RtcConnection.setBufferedAmountLowThreshold: channelId")
                val a1 = (if (1 < n) r.f64() else null) ?: return settle.reject("bad arguments — RtcConnection.setBufferedAmountLowThreshold: threshold")
                plugin.setBufferedAmountLowThreshold(a0, a1, Reply<Unit, RtcConnectionCode>(settle, null))
            }
            "closeDataChannel" -> {
                val a0 = (if (0 < n) r.i32() else null) ?: return settle.reject("bad arguments — RtcConnection.closeDataChannel: channelId")
                plugin.closeDataChannel(a0, Reply<Unit, RtcConnectionCode>(settle, null))
            }
            else -> settle.reject("Unknown method: $method")
        }
    }
}

// ---- RtcVideo ----

/** The codes the calls of "rtcVideo" reject with. */
enum class RtcVideoCode(override val code: String) : PluginCode {
    NOT_FOUND("notFound"),
}

/** The events of "rtcVideo": what the plugin sends the app. From the main thread. */
class RtcVideoEvents(private val channel: PluginEmit) {
    /** The first frame was drawn, and every change of the picture's size after. */
    fun resize(width: Int, height: Int) {
        val w = PackedWriter()
        w.beginObject()
        w.key("width"); w.i32(width)
        w.key("height"); w.i32(height)
        w.end()
        this.channel.emit("resize", w.bytes())
    }
}

/**
 * A view drawing one video track, local or remote.
 *
 * What the plugin implements. A call arrives on the main thread; its reply is settled exactly
 * once, now or later.
 */
interface RtcVideoPlugin {
    /** The view the host mounts, fullscreen: a View is a destination, never a node of a layout (a node is a UIHostNode). */
    val view: android.view.View

    /**
     * Draw another track; null = black.
     * Rejects with NOT_FOUND.
     */
    fun setTrack(trackId: String?, reply: Reply<Unit, RtcVideoCode>)

    fun setObjectFit(fit: ObjectFit, reply: Reply<Unit, RtcVideoCode>)

    fun setMirror(mirror: Boolean, reply: Reply<Unit, RtcVideoCode>)

    /** The instance goes (the world swapped): release the hardware. */
    fun destroy() {}
}

object RtcVideoChannel {
    /** What the halves register under. */
    const val NAME = "rtcVideo"

    /** The contract's version: the highest `@since` of its members. */
    const val VERSION = 1

    /** Register the view: `make` builds one instance from its params. */
    fun register(engine: LecodesEngine, make: (params: RtcVideoParams, events: RtcVideoEvents) -> RtcVideoPlugin) {
        engine.registerView(NAME, VERSION) { params, channel ->
            val plugin = make(RtcVideoParams.read(Wire.reader(params)) ?: RtcVideoParams(), RtcVideoEvents { event, packed -> channel.emitPacked(event, packed) })
            NativeViews.Instance(plugin.view, onCall = { call -> RtcVideoGlue.call(plugin, call.method, call.reader(), call) }, onDestroy = { plugin.destroy() })
        }
    }
}

/** Reads a call off the wire and hands it to the plugin; a malformed call never reaches it. */
internal object RtcVideoGlue {
    fun call(plugin: RtcVideoPlugin, method: String, r: PackedReader, settle: ChannelSettle) {
        val n = r.beginArray()   // the arguments, in their order
        when (method) {
            "setTrack" -> {
                val a0 = if (0 < n && !r.isNull()) (r.string() ?: return settle.reject("bad arguments — RtcVideo.setTrack: trackId")) else { if (0 < n) r.skip(); null }
                plugin.setTrack(a0, Reply<Unit, RtcVideoCode>(settle, null))
            }
            "setObjectFit" -> {
                val a0 = (if (0 < n) ObjectFit.read(r) else null) ?: return settle.reject("bad arguments — RtcVideo.setObjectFit: fit")
                plugin.setObjectFit(a0, Reply<Unit, RtcVideoCode>(settle, null))
            }
            "setMirror" -> {
                val a0 = (if (0 < n) r.bool() else null) ?: return settle.reject("bad arguments — RtcVideo.setMirror: mirror")
                plugin.setMirror(a0, Reply<Unit, RtcVideoCode>(settle, null))
            }
            else -> settle.reject("Unknown method: $method")
        }
    }
}

// ---- UIRTCVideo ----

/** The codes the calls of "rtcVideo" reject with. */
enum class UIRTCVideoNodeCode(override val code: String) : PluginCode {
    NOT_FOUND("notFound"),
}

/** The events of the host node "rtcVideo": what the plugin sends the app. Any thread. */
class UIRTCVideoNodeEvents(private val channel: HostNodeChannel) {
    /** The first frame was drawn, and every change of the picture's size after. */
    fun resize(width: Int, height: Int) {
        val w = PackedWriter()
        w.beginObject()
        w.key("width"); w.i32(width)
        w.key("height"); w.i32(height)
        w.end()
        this.channel.emitPacked("resize", w.bytes())
    }
}

/**
 * One video track, local or remote, as a node of the layout: a box in a screen, sized by its
 * styles, black where there is no picture; the holder paints the box (radius, border, shadow) over
 * it.
 *
 * What the plugin implements: one instance per node of the kind, made when the SDK creates the
 * node, called on the main thread. `view` is laid out and painted as the node's box; a call's reply
 * is settled exactly once, now or later.
 */
interface UIRTCVideoNodeInstance : HostNodeInstance {
    /** The track to draw; none = black. */
    fun setTrackId(value: String?)
    /** Default "cover". */
    fun setObjectFit(value: ObjectFit?)
    /** Flip horizontally — the front camera's preview. Default false. */
    fun setMirror(value: Boolean?)

    /**
     * Draw another track; null = black.
     * Rejects with NOT_FOUND.
     */
    fun setTrack(trackId: String?, reply: Reply<Unit, UIRTCVideoNodeCode>)
    fun setObjectFit(fit: ObjectFit, reply: Reply<Unit, UIRTCVideoNodeCode>)
    fun setMirror(mirror: Boolean, reply: Reply<Unit, UIRTCVideoNodeCode>)

    // ---- what the holder (UINodeHost) hands the instance, by name: read by the contract here — the
    // plugin implements none of it ----
    override fun setProperty(name: String, value: String?) = UIRTCVideoNodeGlue.setProperty(this, name, value)
    override fun setStyle(name: String, color: Int?) {}
    override fun setStyle(name: String, number: Double?) {}
    /** Never asked: the node's styles size it. */
    override fun measure(c: HostNodeConstraints): SizeF = SizeF(0f, 0f)
    override fun call(method: String, r: PackedReader, settle: ChannelSettle) = UIRTCVideoNodeGlue.call(this, method, r, settle)
    /** The holder paints the whole box. */
    override val paintsSelf: Boolean get() = false
}

/** The host node "rtcVideo": its registration, and the glue between the holder and the instance. */
object UIRTCVideoNodeGlue {
    /** What the halves register under: the node's kind. */
    const val NAME = "rtcVideo"

    /** The contract's version: the highest `@since` of its members. */
    const val VERSION = 1

    /** Register the node: `make` builds one instance per node of the kind, when the SDK creates one. */
    fun register(engine: LecodesEngine, make: (events: UIRTCVideoNodeEvents) -> UIRTCVideoNodeInstance) {
        engine.registerNode(NAME, VERSION) { channel -> make(UIRTCVideoNodeEvents(channel)) }
    }

    /** A prop the SDK wrote: its text, null when it was cleared. */
    internal fun setProperty(i: UIRTCVideoNodeInstance, name: String, value: String?) {
        when (name) {
            "trackId" -> i.setTrackId(value)
            "objectFit" -> i.setObjectFit(if (value == null) null else ObjectFit.values().firstOrNull { it.wire == value } ?: return dropped(name))
            "mirror" -> i.setMirror(if (value == null) null else bool(value) ?: return dropped(name))
            else -> {}   // `kind` (the holder's), or a prop of a newer contract
        }
    }

    /** A call of the SDK: read off the wire and handed to the instance; a malformed call never reaches it. */
    internal fun call(i: UIRTCVideoNodeInstance, method: String, r: PackedReader, settle: ChannelSettle) {
        val n = r.beginArray()   // the arguments, in their order
        when (method) {
            "setTrack" -> {
                val a0 = if (0 < n && !r.isNull()) (r.string() ?: return settle.reject("bad arguments — UIRTCVideo.setTrack: trackId")) else { if (0 < n) r.skip(); null }
                i.setTrack(a0, Reply<Unit, UIRTCVideoNodeCode>(settle, null))
            }
            "setObjectFit" -> {
                val a0 = (if (0 < n) ObjectFit.read(r) else null) ?: return settle.reject("bad arguments — UIRTCVideo.setObjectFit: fit")
                i.setObjectFit(a0, Reply<Unit, UIRTCVideoNodeCode>(settle, null))
            }
            "setMirror" -> {
                val a0 = (if (0 < n) r.bool() else null) ?: return settle.reject("bad arguments — UIRTCVideo.setMirror: mirror")
                i.setMirror(a0, Reply<Unit, UIRTCVideoNodeCode>(settle, null))
            }
            else -> settle.reject("Unknown method: $method")
        }
    }

    private fun bool(text: String?): Boolean? = when (text) { "1" -> true; "0" -> false; else -> null }

    private fun dropped(prop: String) {
        android.util.Log.w("LeCodes", "the node \"$NAME\" dropped a value of $prop its contract does not read")
    }
}
